// [vite-esm] imports auto-generated by the 2026-07 Vite migration.
import "../state.js";

/* Per-cell renderer for the pivot engine.
 *
 * Given:
 *   cards    — array of card objects (can be empty, one, or many)
 *   report   — the active PrintReport (carries elementStyles[])
 *   school   — the school document (for entity name/abbr lookups)
 *
 * Returns a DOM node sized to fill the parent cell. Handles multi-card-
 * per-cell rendering by joining element strings with commas (H1).
 * Multi-class activity cards render the Class element with slashes (H6).
 *
 * Phase 1 scope: honour enabled / size / anchor / bold / italic / underline
 * per element. Defer Set-for-more, font-family override per element,
 * text-shrink-to-fit (Phase 7), and conditional toggles (Phase 2 polish).
 */
(function () {
  "use strict";
  const APP = (window.APP = window.APP || {});

  const ANCHOR_TO_FLEX = {
    "top-left":      { justify: "flex-start", align: "flex-start", text: "left" },
    "top-center":    { justify: "flex-start", align: "center",      text: "center" },
    "top-right":     { justify: "flex-start", align: "flex-end",   text: "right" },
    "middle-left":   { justify: "center",     align: "flex-start", text: "left" },
    "middle-center": { justify: "center",     align: "center",     text: "center" },
    "middle-right":  { justify: "center",     align: "flex-end",   text: "right" },
    "bottom-left":   { justify: "flex-end",   align: "flex-start", text: "left" },
    "bottom-center": { justify: "flex-end",   align: "center",     text: "center" },
    "bottom-right":  { justify: "flex-end",   align: "flex-end",   text: "right" },
  };

  function el(tag, attrs, ...kids) {
    const n = document.createElement(tag);
    if (attrs) for (const k in attrs) {
      const v = attrs[k]; if (v == null) continue;
      if (k === "class") n.className = v;
      else if (k.startsWith("on") && typeof v === "function") n.addEventListener(k.slice(2), v);
      else n.setAttribute(k, v);
    }
    for (const c of kids) if (c != null && c !== false) {
      n.appendChild(typeof c === "string" ? document.createTextNode(c) : c);
    }
    return n;
  }

  function elementStyleFor(report, key) {
    const styles = report?.elementStyles || [];
    return styles.find(s => s.key === key) || { enabled: false };
  }

  function entityName(school, kind, id, fmt) {
    const list = {
      subject: school.subjects, teacher: school.teachers,
      class: school.classes, classroom: school.classrooms,
      group: school.groups, student: school.students,
    }[kind] || [];
    const ent = list.find(e => e.id === id);
    if (!ent) return id || "";
    if (fmt === "full") return ent.name || ent.id;
    return ent.abbreviation || ent.shortName || ent.name || ent.id;
  }

  function entityColor(school, kind, id) {
    const list = {
      subject: school.subjects, teacher: school.teachers,
      class: school.classes, classroom: school.classrooms,
    }[kind] || [];
    const ent = list.find(e => e.id === id);
    return ent?.color || null;
  }

  /** Multi-card label join: comma for most elements, slash for Class element
   *  when one card spans multiple classes (the H6 multi-class case).
   *  Honours style.labelOverride — when set, returns that fixed string. */
  function joinElementLabels(cards, key, school, style) {
    if (style.labelOverride && String(style.labelOverride).trim().length > 0 && cards.length > 0) {
      return String(style.labelOverride).trim();
    }
    const fmt = style.textFormat || "abbreviation";
    if (key === "subject") {
      const seen = new Set();
      const out = [];
      for (const c of cards) {
        if (!c.subjectId || seen.has(c.subjectId)) continue;
        seen.add(c.subjectId);
        out.push(entityName(school, "subject", c.subjectId, fmt));
      }
      return out.join(", ");
    }
    if (key === "teacher") {
      const seen = new Set();
      const out = [];
      for (const c of cards) {
        for (const tid of (c.teacherIds || [])) {
          if (seen.has(tid)) continue;
          seen.add(tid);
          out.push(entityName(school, "teacher", tid, fmt));
        }
      }
      const MAX_TEACHERS = 3;
      return out.length > MAX_TEACHERS
        ? out.slice(0, MAX_TEACHERS).join(" / ") + " …"
        : out.join(" / ");
    }
    if (key === "class") {
      if (style.conditional?.printGroupInsteadOfClass) {
        return joinElementLabels(cards, "group", school, style);
      }
      // Per-card class lists join with slashes (multi-class activity),
      // then card-to-card joins with commas (multi-card-per-cell).
      const parts = [];
      for (const c of cards) {
        const ids = c.classIds || [];
        if (ids.length === 0) continue;
        const slashed = ids.map(id => entityName(school, "class", id, fmt)).join("/");
        parts.push(slashed);
      }
      // Dedupe by string
      return Array.from(new Set(parts)).join(", ");
    }
    if (key === "classroom") {
      const seen = new Set();
      const out = [];
      for (const c of cards) {
        const rid = c.roomId || (c.roomIds && c.roomIds[0]);
        if (!rid || seen.has(rid)) continue;
        seen.add(rid);
        const r = entityName(school, "classroom", rid, fmt);
        if (style.conditional?.doNotPrintIfHomeClassroom) {
          // Skip if this is the home classroom of any class on the card
          const classRooms = (c.classIds || []).map(cid => {
            const cls = (school.classes || []).find(cc => cc.id === cid);
            return [cls?.homeRoomId, cls?.classroomId].concat(cls?._classroomIds || []);
          }).flat().filter(Boolean);
          if (classRooms.includes(rid)) continue;
        }
        out.push(r);
      }
      return out.join(", ");
    }
    if (key === "group") {
      const seen = new Set();
      const out = [];
      for (const c of cards) {
        for (const gid of (c.groupIds || [])) {
          if (seen.has(gid)) continue;
          seen.add(gid);
          // "Do not print if entire class" — skip group label when the
          // group represents the whole class
          if (style.conditional?.doNotPrintIfEntireClass) {
            const g = (school.groups || []).find(gg => gg.id === gid);
            if (g?.entireClass) continue;
          }
          out.push(entityName(school, "group", gid, fmt));
        }
      }
      return out.join(", ");
    }
    if (key === "count") {
      return String(cards.length);
    }
    if (key === "bellTimes") {
      const seen = new Set();
      const out = [];
      for (const c of cards) {
        const key = c.day + "_" + c.period;
        if (seen.has(key)) continue;
        seen.add(key);
        const t = lookupBellTime(school, c.period);
        if (t) out.push(t);
      }
      return out.join(", ");
    }
    return "";
  }

  function lookupBellTime(school, period) {
    const bell = school?.bell || school?.bells?.[0];
    if (!bell || !bell.periods) return "";
    const p = bell.periods[period - 1];
    if (!p) return "";
    const start = p.start || fmtMin(p.startMin);
    const end = p.end || fmtMin(p.endMin);
    return start + (end ? "–" + end : "");
  }

  function fmtMin(min) {
    if (min == null || min < 0) return "";
    return Math.floor(min / 60) + ":" + String(min % 60).padStart(2, "0");
  }

  function renderElement(text, style) {
    if (!text || !style.enabled) return null;
    const fontStyle = [];
    if (style.bold)      fontStyle.push("font-weight:700");
    if (style.italic)    fontStyle.push("font-style:italic");
    if (style.underline) fontStyle.push("text-decoration:underline");
    if (style.font && style.font !== "system-ui") fontStyle.push("font-family:'" + style.font + "', system-ui");
    // Phase 7 — text-shrink-to-fit. Use container-query units (cqi) for size
    // when supported, clamped between a 6px floor and the configured % as
    // the ceiling. Browsers that don't support container queries gracefully
    // fall back to the second clamp arg.
    const ceilingPx = Math.max(7, Math.round((style.size || 14) * 0.6));
    const floorPx = 6;
    fontStyle.push("font-size:clamp(" + floorPx + "px, " + Math.max(6, Math.round((style.size || 14) * 0.35)) + "cqi, " + ceilingPx + "px)");
    fontStyle.push("overflow-wrap:break-word");
    fontStyle.push("word-break:break-word");
    fontStyle.push("hyphens:auto");
    fontStyle.push("max-width:100%");
    return el("div", {
      style: "line-height:1.15;" + fontStyle.join(";"),
    }, text);
  }

  function uniqueLabels(cards, key, school) {
    const out = [];
    const seen = new Set();
    function add(v) {
      if (!v || seen.has(v)) return;
      seen.add(v);
      out.push(v);
    }
    for (const c of cards || []) {
      if (key === "class") {
        for (const id of (c.classIds || [])) add(entityName(school, "class", id, "abbreviation"));
      } else if (key === "teacher") {
        for (const id of (c.teacherIds || [])) add(entityName(school, "teacher", id, "abbreviation"));
      } else if (key === "subject") {
        add(entityName(school, "subject", c.subjectId, "abbreviation"));
      } else if (key === "classroom") {
        const rid = c.roomId || (c.roomIds || [])[0];
        add(entityName(school, "classroom", rid, "abbreviation"));
      }
    }
    return out;
  }

  function renderAggregateCell(cards, report, school) {
    cards = cards || [];
    const layout = report?._layout || {};
    const minHeight = Math.max(18, layout.cellMinHeightPx || 48);
    const cell = el("div", {
      class: "chrx-pivot-cell chrx-pivot-cell--aggregate",
      style: "width:100%;height:100%;min-height:" + minHeight + "px;position:relative;container-type:inline-size;padding:2px 4px;box-sizing:border-box",
    });
    if (!cards.length) return cell;

    const kind = report?.cells || "draw-lessons";
    const count = cards.length;
    const lessons = uniqueLabels(cards, "subject", school);
    const teachers = uniqueLabels(cards, "teacher", school);
    const classes = uniqueLabels(cards, "class", school);
    const rooms = uniqueLabels(cards, "classroom", school);

    if (kind === "count-placed") {
      // ASC "Summary timetable of subjects" cell: a bold count pinned to the
      // top-right corner, then the list of classes that take this row's
      // subject in this day+period. The class list is in normal flow (not
      // absolutely positioned) so the table row grows to fit it instead of
      // the text overflowing into neighbouring cells. Teachers and rooms are
      // intentionally omitted to stay compact like ASC.
      cell.style.padding = "1px 2px";
      cell.style.height = "auto";
      cell.appendChild(el("div", {
        style: "position:absolute;right:2px;top:1px;font-size:clamp(6px,20cqi,11px);font-weight:700;line-height:1;z-index:1",
      }, String(count)));
      cell.appendChild(el("div", {
        style: "font-size:clamp(4.5px,10cqi,7px);line-height:1.1;color:var(--chrx-fg);text-align:center;overflow-wrap:anywhere;word-break:break-word;padding-top:1px",
      }, classes.length ? classes.join(", ") : ""));
      return cell;
    }

    if (kind === "count-lessons") {
      cell.appendChild(el("div", {
        style: "display:flex;width:100%;height:100%;align-items:center;justify-content:center;font-weight:700;font-size:clamp(8px,24cqi,14px)",
      }, String(count)));
      return cell;
    }

    if (kind === "teacher-list-with-count") {
      const title = teachers.length ? teachers.join(", ") : lessons.join(", ");
      cell.appendChild(el("div", {
        style: "font-weight:700;font-size:clamp(7px,18cqi,11px);line-height:1.12;overflow-wrap:anywhere",
      }, title || String(count)));
      cell.appendChild(el("div", {
        style: "position:absolute;right:3px;bottom:2px;font-size:clamp(6px,13cqi,9px);color:var(--chrx-fg-secondary)",
      }, String(count)));
      return cell;
    }

    return renderCell(cards, report, school);
  }

  function getCardBgColor(cards, report, school) {
    if (!report.colors?.cardOn) return null;
    const key = report.colors.cardKey || "subject";
    if (cards.length === 0) return null;
    const card = cards[0];
    // aSc convention: cards with no teacher (free / leisure / self-study
    // periods) print white, so coloured teaching cards stand out against
    // them. This wins over the colour key.
    const hasTeacher = (card.teacherIds || []).length > 0;
    if (!hasTeacher) return isDarkTheme() ? "var(--chrx-bg-tile)" : "#ffffff";
    let id = null;
    if (key === "subject")   id = card.subjectId;
    else if (key === "teacher")   id = (card.teacherIds || [])[0];
    else if (key === "class")     id = (card.classIds || [])[0];
    else if (key === "classroom") id = card.roomId || (card.roomIds || [])[0];
    if (!id) return null;
    return entityColor(school, key, id);
  }

  function isDarkTheme() {
    return typeof document !== "undefined" &&
      document.documentElement &&
      document.documentElement.getAttribute("data-theme") === "dark";
  }

  function ordinal(n) {
    const suff = ["th","st","nd","rd"];
    const v = n % 100;
    return n + (suff[(v-20)%10] || suff[v] || suff[0]);
  }

  function printPeriods(school) {
    const periods = school?._printPeriods || school?.bell?.periods || [];
    return Array.isArray(periods) ? periods : [];
  }

  function periodIndexValue(p, i) {
    return p && p.index != null ? (p.index | 0) : i + 1;
  }

  function periodEntityForCard(card, school) {
    const periods = printPeriods(school);
    const period = (card && card.period) | 0;
    for (let i = 0; i < periods.length; i++) {
      const p = periods[i] || {};
      const idx = periodIndexValue(p, i);
      if (idx === period) {
        const label = p.label ? String(p.label) : ordinal(i + 1);
        const displayLabel = /^\d+$/.test(label) ? ordinal(Number(label)) : label;
        return { ...p, index: idx, label: displayLabel, abbr: displayLabel };
      }
    }
    return null;
  }

  function breakAfterPeriod(periods, idx, school) {
    if (!school || !school.breaks || !school.breaks.length) return null;
    if (idx >= periods.length - 1) return null;
    const p1 = periods[idx], p2 = periods[idx + 1];
    if (!p1 || !p2 || p1.endMin == null || p2.startMin == null) return null;
    const t1 = p1.endMin, t2 = p2.startMin;
    if (t2 <= t1) return null;
    for (const b of school.breaks) {
      const bs = timeToMin(b.starttime), be = timeToMin(b.endtime);
      if (bs !== -1 && be !== -1 && bs >= t1 - 5 && be <= t2 + 5) return b;
    }
    return null;
  }

  function breakAfterCardPeriod(cards, idx, school) {
    const p1 = periodEntityForCard(cards[idx], school);
    const p2 = periodEntityForCard(cards[idx + 1], school);
    if (!p1 || !p2 || p1.index === p2.index) return null;
    const periods = printPeriods(school);
    let start = -1, end = -1;
    for (let i = 0; i < periods.length; i++) {
      const idxValue = periodIndexValue(periods[i], i);
      if (idxValue === p1.index) start = i;
      if (idxValue === p2.index) end = i;
    }
    if (start < 0 || end < 0 || end <= start) return null;
    for (let i = start; i < end; i++) {
      const brk = breakAfterPeriod(periods, i, school);
      if (brk) return brk;
    }
    return null;
  }

  function timeToMin(timeStr) {
    if (!timeStr) return -1;
    const m = String(timeStr).match(/^(\d{1,2}):(\d{2})$/);
    if (!m) return -1;
    return parseInt(m[1], 10) * 60 + parseInt(m[2], 10);
  }

  function teacherLabel(card, school) {
    const ids = (card && card.teacherIds) || [];
    const first = ids[0];
    return first ? entityName(school, "teacher", first, "abbreviation") : "";
  }

  function roomLabel(card, school) {
    const rid = card?.roomId || (card?.roomIds && card.roomIds[0]);
    return rid ? entityName(school, "classroom", rid, "abbreviation") : "";
  }

  function truncateText(text, maxChars) {
    text = String(text || "");
    if (text.length <= maxChars) return text;
    return maxChars <= 1 ? text.slice(0, 1) : text.slice(0, maxChars - 1) + "…";
  }

  function ascSubjectLines(text, widthPx, fontPx, maxLines) {
    const words = String(text || "").split(/\s+/).filter(Boolean);
    if (!words.length) return ["·"];
    const charsPerLine = Math.max(2, Math.floor((widthPx || 18) / Math.max(3, (fontPx || 7) * 0.55)));
    const lines = [];
    for (const word of words) {
      if (word.length <= charsPerLine) {
        lines.push(word);
      } else {
        for (let i = 0; i < word.length; i += charsPerLine) {
          lines.push(truncateText(word.slice(i, i + charsPerLine), charsPerLine));
        }
      }
    }
    if (lines.length <= maxLines) return lines;
    if (maxLines <= 1) return [truncateText(words.join(" "), charsPerLine)];
    const kept = lines.slice(0, Math.max(1, maxLines - 1));
    kept[kept.length - 1] = truncateText(words[words.length - 1] || words.join(" "), charsPerLine);
    return kept;
  }

  function renderSummaryClassDayCell(cards, report, school) {
    cards = (cards || []).slice();
    const layout = report?._layout || {};
    const fontPx = layout.summaryDayFontPx || 7.5;
    const linePx = layout.summaryDayLineHeightPx || 8.6;
    const periodMode = report.cells === "summary-class-day-period";
    const maxLines = Math.max(1, Math.floor((layout.cellMinHeightPx || 48) / Math.max(6.8, linePx)));
    const cell = el("div", {
      class: "chrx-pivot-cell chrx-pivot-cell--summary-day",
      style: "width:100%;height:100%;min-height:" + Math.max(18, layout.cellMinHeightPx || 48) + "px;padding:2px 1px;box-sizing:border-box;overflow:hidden;font-family:Arial,sans-serif;font-size:" + fontPx + "px;line-height:" + linePx + "px;text-align:center;display:flex;flex-direction:column;justify-content:center;align-items:center",
    });
    if (!cards.length) return cell;

    cards.sort((a, b) => {
      const pa = periodEntityForCard(a, school);
      const pb = periodEntityForCard(b, school);
      return (pa?.index || a.period || 0) - (pb?.index || b.period || 0)
        || String(a.lessonId || "").localeCompare(String(b.lessonId || ""));
    });

    const showMeta = !!layout.summaryDayShowMeta;
    const renderedLines = [];
    const seenLines = new Set();
    cards.forEach((card, ci) => {
      const period = periodEntityForCard(card, school);
      const label = period?.abbr || period?.label || String(card.period || "");
      const subject = entityName(school, "subject", card.subjectId, "abbreviation") || "·";
      const meta = showMeta && !periodMode ? [teacherLabel(card, school), roomLabel(card, school)].filter(Boolean).join(" · ") : "";
      const lines = periodMode
        ? ascSubjectLines(subject, layout.summaryDayPeriodColWidthPx || 18, fontPx, maxLines)
        : [label + " " + subject + (meta ? " · " + meta : "")];
      for (const line of lines) {
        if (!seenLines.has(line)) {
          seenLines.add(line);
          renderedLines.push(line);
        }
      }
      if (!periodMode) {
        const brk = breakAfterCardPeriod(cards, ci, school);
        if (brk) {
          renderedLines.push(brk.printtext || brk.name || "BREAK");
        }
      }
    });
    for (const line of renderedLines.slice(0, periodMode ? maxLines : renderedLines.length)) {
      cell.appendChild(el("div", {
        style: "white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%;color:var(--chrx-fg)",
      }, line));
    }

    return cell;
  }

  function renderSummaryClassDayPeriodCell(cards, report, school) {
    cards = cards || [];
    const layout = report?._layout || {};
    const minHeight = Math.max(18, layout.cellMinHeightPx || 22);
    const cell = el("div", {
      class: "chrx-pivot-cell chrx-pivot-cell--summary-day",
      style: "width:100%;height:100%;min-height:" + minHeight + "px;padding:2px 3px;box-sizing:border-box;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;overflow:hidden;position:relative",
    });
    if (cards.length === 0) return cell;

    const bg = getCardBgColor(cards, report, school);
    if (bg) {
      cell.style.background = bg;
      cell._bgColor = bg;
    }

    const rowDims = report.rows || [];
    const isClassRow = rowDims.includes("class");
    const isTeacherRow = rowDims.includes("teacher");
    const isRoomRow = rowDims.includes("classroom");

    // Gather distinct subjects
    const subjects = [];
    const seenSubj = new Set();
    for (const c of cards) {
      if (!c.subjectId || seenSubj.has(c.subjectId)) continue;
      seenSubj.add(c.subjectId);
      subjects.push(entityName(school, "subject", c.subjectId, "abbreviation"));
    }

    // Secondary line depending on row context:
    const secondaryList = [];
    if (isClassRow) {
      // Row is Class -> show Teacher(s) + non-home Room (never redundant class name)
      const teachers = [];
      const seenT = new Set();
      for (const c of cards) {
        for (const tid of (c.teacherIds || [])) {
          if (seenT.has(tid)) continue;
          seenT.add(tid);
          teachers.push(entityName(school, "teacher", tid, "abbreviation"));
        }
      }
      if (teachers.length > 0) {
        secondaryList.push(teachers.slice(0, 2).join("/"));
      }
      const rooms = [];
      const seenR = new Set();
      for (const c of cards) {
        const rid = c.roomId || (c.roomIds && c.roomIds[0]);
        if (rid && !seenR.has(rid)) {
          seenR.add(rid);
          rooms.push(entityName(school, "classroom", rid, "abbreviation"));
        }
      }
      if (rooms.length > 0) {
        secondaryList.push("(" + rooms[0] + ")");
      }
    } else if (isTeacherRow) {
      // Row is Teacher -> show Class(es) + non-home Room
      const classes = [];
      const seenC = new Set();
      for (const c of cards) {
        for (const cid of (c.classIds || [])) {
          if (seenC.has(cid)) continue;
          seenC.add(cid);
          classes.push(entityName(school, "class", cid, "abbreviation"));
        }
      }
      if (classes.length > 0) {
        secondaryList.push(classes.join("/"));
      }
      const rooms = [];
      const seenR = new Set();
      for (const c of cards) {
        const rid = c.roomId || (c.roomIds && c.roomIds[0]);
        if (rid && !seenR.has(rid)) {
          seenR.add(rid);
          rooms.push(entityName(school, "classroom", rid, "abbreviation"));
        }
      }
      if (rooms.length > 0) {
        secondaryList.push("(" + rooms[0] + ")");
      }
    } else if (isRoomRow) {
      // Row is Room -> show Class(es)
      const classes = [];
      const seenC = new Set();
      for (const c of cards) {
        for (const cid of (c.classIds || [])) {
          if (seenC.has(cid)) continue;
          seenC.add(cid);
          classes.push(entityName(school, "class", cid, "abbreviation"));
        }
      }
      if (classes.length > 0) {
        secondaryList.push(classes.join("/"));
      }
    }

    // Line 1: Subject (bold, clean)
    const subjText = subjects.join(" / ");
    if (subjText) {
      const subjDiv = el("div", {
        style: "font-weight:700;font-size:clamp(6.5px, 12cqi, 9.5px);line-height:1.15;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--chrx-fg, #111)",
      }, subjText);
      cell.appendChild(subjDiv);
    }

    // Line 2: Secondary info
    const secText = secondaryList.join(" ");
    if (secText) {
      const secDiv = el("div", {
        style: "font-size:clamp(5.5px, 10cqi, 8px);line-height:1.1;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--chrx-fg-secondary, #444);margin-top:1px",
      }, secText);
      cell.appendChild(secDiv);
    }

    return cell;
  }

  function renderCell(cards, report, school) {
    cards = cards || [];
    const layout = report?._layout || {};
    const minHeight = Math.max(18, layout.cellMinHeightPx || 48);
    const cell = el("div", {
      class: "chrx-pivot-cell",
      style: "width:100%;height:100%;min-height:" + minHeight + "px;position:relative;container-type:inline-size",
    });
    if (cards.length === 0) return cell;

    const bg = getCardBgColor(cards, report, school);
    if (bg) {
      cell.style.background = bg;
      cell._bgColor = bg;
    }

    // Collect enabled elements grouped by anchor key so that elements sharing
    // the same anchor (e.g. teacher + classroom) stack on separate lines in
    // one wrapper rather than each getting their own overlapping absolute div.
    const ELEMENT_KEYS = ["subject","teacher","class","group","classroom","count","bellTimes"];
    const byAnchor = new Map();
    for (const key of ELEMENT_KEYS) {
      const style = elementStyleFor(report, key);
      if (!style.enabled) continue;
      const text = joinElementLabels(cards, key, school, style);
      if (!text) continue;
      const anchorKey = style.anchor || "middle-center";
      if (!byAnchor.has(anchorKey)) byAnchor.set(anchorKey, []);
      byAnchor.get(anchorKey).push({ text, style });
    }

    for (const [anchorKey, items] of byAnchor) {
      const anchor = ANCHOR_TO_FLEX[anchorKey] || ANCHOR_TO_FLEX["middle-center"];
      const wrap = el("div", {
        style: "position:absolute;inset:0;display:flex;flex-direction:column;justify-content:" + anchor.justify +
          ";align-items:" + anchor.align +
          ";text-align:" + anchor.text +
          ";padding:2px 4px;pointer-events:none",
      });
      for (const { text, style } of items) {
        const elNode = renderElement(text, style);
        if (elNode) wrap.appendChild(elNode);
      }
      cell.appendChild(wrap);
    }

    return cell;
  }

  APP.PrintCellRenderer = {
    renderCell,
    renderSummaryClassDayCell,
    renderSummaryClassDayPeriodCell,
    joinElementLabels,
  };
  APP.PrintCellRenderer.renderAggregateCell = renderAggregateCell;
})();
